SELECT 
    'ADAPI' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_ADAPI.FOLHA FO 
    JOIN SW_ADAPI.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_ADAPI.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_ADAPI.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_ADAPI.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_ADAPI.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_ADAPI.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_ADAPI.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_ADAPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_ADAPI.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_ADAPI.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_ADAPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_ADAPI.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_ADAPI.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_ADAPI.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_ADAPI.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_ADAPI.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_ADAPI.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_ADAPI.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_ADAPI.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_ADAPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_ADAPI.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_ADAPI.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_ADAPI.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'ADH' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_ADH.FOLHA FO 
    JOIN SW_ADH.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_ADH.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_ADH.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_ADH.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_ADH.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_ADH.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_ADH.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_ADH.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_ADH.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_ADH.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_ADH.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_ADH.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_ADH.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_ADH.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_ADH.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_ADH.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_ADH.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_ADH.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_ADH.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_ADH.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_ADH.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_ADH.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_ADH.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'AGESPISA' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_AGESPISA.FOLHA FO 
    JOIN SW_AGESPISA.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_AGESPISA.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_AGESPISA.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_AGESPISA.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_AGESPISA.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_AGESPISA.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_AGESPISA.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_AGESPISA.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_AGESPISA.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_AGESPISA.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_AGESPISA.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_AGESPISA.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_AGESPISA.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_AGESPISA.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_AGESPISA.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_AGESPISA.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_AGESPISA.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_AGESPISA.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_AGESPISA.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_AGESPISA.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_AGESPISA.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_AGESPISA.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_AGESPISA.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'AGESPISA02' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_AGESPISA02.FOLHA FO 
    JOIN SW_AGESPISA02.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_AGESPISA02.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_AGESPISA02.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_AGESPISA02.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_AGESPISA02.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_AGESPISA02.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_AGESPISA02.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_AGESPISA02.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_AGESPISA02.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_AGESPISA02.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_AGESPISA02.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_AGESPISA02.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_AGESPISA02.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_AGESPISA02.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_AGESPISA02.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_AGESPISA02.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_AGESPISA02.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_AGESPISA02.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_AGESPISA02.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_AGESPISA02.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_AGESPISA02.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_AGESPISA02.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_AGESPISA02.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

