    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_AGRESP.FOLHA FO 
    JOIN SW_AGRESP.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_AGRESP.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_AGRESP.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_AGRESP.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_AGRESP.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_AGRESP.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_AGRESP.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_AGRESP.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_AGRESP.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_AGRESP.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_AGRESP.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_AGRESP.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_AGRESP.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_AGRESP.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_AGRESP.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_AGRESP.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_AGRESP.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_AGRESP.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_AGRESP.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_AGRESP.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_AGRESP.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_AGRESP.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_AGRESP.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'BEP' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_BEP.FOLHA FO 
    JOIN SW_BEP.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_BEP.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_BEP.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_BEP.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_BEP.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_BEP.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_BEP.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_BEP.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_BEP.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_BEP.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_BEP.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_BEP.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_BEP.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_BEP.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_BEP.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_BEP.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_BEP.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_BEP.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_BEP.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_BEP.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_BEP.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_BEP.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_BEP.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'CBMPI' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_CBMPI.FOLHA FO 
    JOIN SW_CBMPI.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_CBMPI.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_CBMPI.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_CBMPI.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_CBMPI.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_CBMPI.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_CBMPI.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_CBMPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_CBMPI.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_CBMPI.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_CBMPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_CBMPI.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_CBMPI.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_CBMPI.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_CBMPI.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_CBMPI.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_CBMPI.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_CBMPI.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_CBMPI.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_CBMPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_CBMPI.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_CBMPI.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_CBMPI.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'CCOM' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_CCOM.FOLHA FO 
    JOIN SW_CCOM.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_CCOM.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_CCOM.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_CCOM.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_CCOM.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_CCOM.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_CCOM.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_CCOM.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_CCOM.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_CCOM.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_CCOM.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_CCOM.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_CCOM.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_CCOM.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_CCOM.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_CCOM.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_CCOM.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_CCOM.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_CCOM.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_CCOM.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_CCOM.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_CCOM.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_CCOM.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'CDTER' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_CDTER.FOLHA FO 
    JOIN SW_CDTER.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_CDTER.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_CDTER.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_CDTER.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_CDTER.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_CDTER.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_CDTER.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_CDTER.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_CDTER.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_CDTER.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_CDTER.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_CDTER.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_CDTER.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_CDTER.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_CDTER.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_CDTER.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_CDTER.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_CDTER.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_CDTER.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_CDTER.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_CDTER.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_CDTER.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_CDTER.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'CENDROGAS' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_CENDROGAS.FOLHA FO 
    JOIN SW_CENDROGAS.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_CENDROGAS.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_CENDROGAS.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_CENDROGAS.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_CENDROGAS.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_CENDROGAS.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_CENDROGAS.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_CENDROGAS.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_CENDROGAS.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_CENDROGAS.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_CENDROGAS.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_CENDROGAS.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_CENDROGAS.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_CENDROGAS.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_CENDROGAS.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_CENDROGAS.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_CENDROGAS.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_CENDROGAS.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_CENDROGAS.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_CENDROGAS.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_CENDROGAS.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_CENDROGAS.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_CENDROGAS.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'COFIR' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_COFIR.FOLHA FO 
    JOIN SW_COFIR.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_COFIR.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_COFIR.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_COFIR.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_COFIR.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_COFIR.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_COFIR.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_COFIR.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_COFIR.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_COFIR.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_COFIR.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_COFIR.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_COFIR.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_COFIR.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_COFIR.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_COFIR.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_COFIR.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_COFIR.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_COFIR.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_COFIR.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_COFIR.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_COFIR.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_COFIR.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'COJUV' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_COJUV.FOLHA FO 
    JOIN SW_COJUV.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_COJUV.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_COJUV.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_COJUV.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_COJUV.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_COJUV.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_COJUV.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_COJUV.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_COJUV.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_COJUV.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_COJUV.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_COJUV.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_COJUV.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_COJUV.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_COJUV.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_COJUV.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_COJUV.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_COJUV.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_COJUV.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_COJUV.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_COJUV.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_COJUV.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_COJUV.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'DEFCIVIL' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_DEFCIVIL.FOLHA FO 
    JOIN SW_DEFCIVIL.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_DEFCIVIL.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_DEFCIVIL.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_DEFCIVIL.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_DEFCIVIL.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_DEFCIVIL.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_DEFCIVIL.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_DEFCIVIL.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_DEFCIVIL.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_DEFCIVIL.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_DEFCIVIL.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_DEFCIVIL.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_DEFCIVIL.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_DEFCIVIL.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_DEFCIVIL.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_DEFCIVIL.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_DEFCIVIL.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_DEFCIVIL.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_DEFCIVIL.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_DEFCIVIL.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_DEFCIVIL.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_DEFCIVIL.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_DEFCIVIL.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'DER' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_DER.FOLHA FO 
    JOIN SW_DER.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_DER.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_DER.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_DER.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_DER.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_DER.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_DER.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_DER.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_DER.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_DER.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_DER.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_DER.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_DER.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_DER.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_DER.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_DER.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_DER.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_DER.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_DER.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_DER.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_DER.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_DER.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_DER.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'DETRAN' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_DETRAN.FOLHA FO 
    JOIN SW_DETRAN.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_DETRAN.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_DETRAN.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_DETRAN.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_DETRAN.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_DETRAN.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_DETRAN.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_DETRAN.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_DETRAN.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_DETRAN.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_DETRAN.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_DETRAN.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_DETRAN.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_DETRAN.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_DETRAN.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_DETRAN.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_DETRAN.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_DETRAN.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_DETRAN.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_DETRAN.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_DETRAN.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_DETRAN.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_DETRAN.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'EMGERPI' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_EMGERPI.FOLHA FO 
    JOIN SW_EMGERPI.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_EMGERPI.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_EMGERPI.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_EMGERPI.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_EMGERPI.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_EMGERPI.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_EMGERPI.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_EMGERPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_EMGERPI.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_EMGERPI.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_EMGERPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_EMGERPI.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_EMGERPI.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_EMGERPI.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_EMGERPI.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_EMGERPI.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_EMGERPI.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_EMGERPI.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_EMGERPI.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_EMGERPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_EMGERPI.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_EMGERPI.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_EMGERPI.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'EMGERPI_CEASA' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_EMGERPI_CEASA.FOLHA FO 
    JOIN SW_EMGERPI_CEASA.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_EMGERPI_CEASA.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_CEASA.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_EMGERPI_CEASA.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_EMGERPI_CEASA.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_EMGERPI_CEASA.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_EMGERPI_CEASA.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_EMGERPI_CEASA.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_EMGERPI_CEASA.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_EMGERPI_CEASA.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_EMGERPI_CEASA.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_EMGERPI_CEASA.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_EMGERPI_CEASA.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_EMGERPI_CEASA.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_EMGERPI_CEASA.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_EMGERPI_CEASA.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_CEASA.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_EMGERPI_CEASA.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_EMGERPI_CEASA.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_CEASA.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_EMGERPI_CEASA.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_CEASA.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_EMGERPI_CEASA.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'EMGERPI_CIDAPI' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_EMGERPI_CIDAPI.FOLHA FO 
    JOIN SW_EMGERPI_CIDAPI.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_EMGERPI_CIDAPI.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_CIDAPI.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_EMGERPI_CIDAPI.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_EMGERPI_CIDAPI.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_EMGERPI_CIDAPI.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_EMGERPI_CIDAPI.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_EMGERPI_CIDAPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_EMGERPI_CIDAPI.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_EMGERPI_CIDAPI.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_EMGERPI_CIDAPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_EMGERPI_CIDAPI.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_EMGERPI_CIDAPI.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_EMGERPI_CIDAPI.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_EMGERPI_CIDAPI.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_EMGERPI_CIDAPI.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_CIDAPI.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_EMGERPI_CIDAPI.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_EMGERPI_CIDAPI.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_CIDAPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_EMGERPI_CIDAPI.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_CIDAPI.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_EMGERPI_CIDAPI.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'EMGERPI_CODIPI' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_EMGERPI_CODIPI.FOLHA FO 
    JOIN SW_EMGERPI_CODIPI.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_EMGERPI_CODIPI.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_CODIPI.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_EMGERPI_CODIPI.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_EMGERPI_CODIPI.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_EMGERPI_CODIPI.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_EMGERPI_CODIPI.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_EMGERPI_CODIPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_EMGERPI_CODIPI.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_EMGERPI_CODIPI.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_EMGERPI_CODIPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_EMGERPI_CODIPI.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_EMGERPI_CODIPI.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_EMGERPI_CODIPI.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_EMGERPI_CODIPI.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_EMGERPI_CODIPI.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_CODIPI.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_EMGERPI_CODIPI.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_EMGERPI_CODIPI.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_CODIPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_EMGERPI_CODIPI.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_CODIPI.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_EMGERPI_CODIPI.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'EMGERPI_COHAB' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_EMGERPI_COHAB.FOLHA FO 
    JOIN SW_EMGERPI_COHAB.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_EMGERPI_COHAB.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_COHAB.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_EMGERPI_COHAB.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_EMGERPI_COHAB.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_EMGERPI_COHAB.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_EMGERPI_COHAB.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_EMGERPI_COHAB.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_EMGERPI_COHAB.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_EMGERPI_COHAB.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_EMGERPI_COHAB.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_EMGERPI_COHAB.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_EMGERPI_COHAB.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_EMGERPI_COHAB.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_EMGERPI_COHAB.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_EMGERPI_COHAB.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_COHAB.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_EMGERPI_COHAB.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_EMGERPI_COHAB.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_COHAB.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_EMGERPI_COHAB.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_COHAB.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_EMGERPI_COHAB.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'EMGERPI_COMDEPI' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_EMGERPI_COMDEPI.FOLHA FO 
    JOIN SW_EMGERPI_COMDEPI.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_EMGERPI_COMDEPI.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_COMDEPI.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_EMGERPI_COMDEPI.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_EMGERPI_COMDEPI.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_EMGERPI_COMDEPI.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_EMGERPI_COMDEPI.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_EMGERPI_COMDEPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_EMGERPI_COMDEPI.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_EMGERPI_COMDEPI.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_EMGERPI_COMDEPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_EMGERPI_COMDEPI.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_EMGERPI_COMDEPI.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_EMGERPI_COMDEPI.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_EMGERPI_COMDEPI.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_EMGERPI_COMDEPI.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_COMDEPI.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_EMGERPI_COMDEPI.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_EMGERPI_COMDEPI.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_COMDEPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_EMGERPI_COMDEPI.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_COMDEPI.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_EMGERPI_COMDEPI.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'EMGERPI_COMEPI' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_EMGERPI_COMEPI.FOLHA FO 
    JOIN SW_EMGERPI_COMEPI.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_EMGERPI_COMEPI.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_COMEPI.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_EMGERPI_COMEPI.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_EMGERPI_COMEPI.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_EMGERPI_COMEPI.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_EMGERPI_COMEPI.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_EMGERPI_COMEPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_EMGERPI_COMEPI.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_EMGERPI_COMEPI.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_EMGERPI_COMEPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_EMGERPI_COMEPI.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_EMGERPI_COMEPI.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_EMGERPI_COMEPI.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_EMGERPI_COMEPI.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_EMGERPI_COMEPI.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_COMEPI.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_EMGERPI_COMEPI.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_EMGERPI_COMEPI.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_COMEPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_EMGERPI_COMEPI.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_COMEPI.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_EMGERPI_COMEPI.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'EMGERPI_CORESA' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_EMGERPI_CORESA.FOLHA FO 
    JOIN SW_EMGERPI_CORESA.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_EMGERPI_CORESA.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_CORESA.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_EMGERPI_CORESA.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_EMGERPI_CORESA.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_EMGERPI_CORESA.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_EMGERPI_CORESA.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_EMGERPI_CORESA.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_EMGERPI_CORESA.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_EMGERPI_CORESA.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_EMGERPI_CORESA.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_EMGERPI_CORESA.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_EMGERPI_CORESA.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_EMGERPI_CORESA.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_EMGERPI_CORESA.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_EMGERPI_CORESA.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_CORESA.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_EMGERPI_CORESA.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_EMGERPI_CORESA.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_CORESA.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_EMGERPI_CORESA.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_CORESA.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_EMGERPI_CORESA.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'EMGERPI_EMATER' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_EMGERPI_EMATER.FOLHA FO 
    JOIN SW_EMGERPI_EMATER.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_EMGERPI_EMATER.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_EMATER.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_EMGERPI_EMATER.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_EMGERPI_EMATER.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_EMGERPI_EMATER.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_EMGERPI_EMATER.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_EMGERPI_EMATER.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_EMGERPI_EMATER.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_EMGERPI_EMATER.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_EMGERPI_EMATER.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_EMGERPI_EMATER.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_EMGERPI_EMATER.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_EMGERPI_EMATER.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_EMGERPI_EMATER.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_EMGERPI_EMATER.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_EMATER.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_EMGERPI_EMATER.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_EMGERPI_EMATER.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_EMATER.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_EMGERPI_EMATER.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_EMATER.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_EMGERPI_EMATER.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'EMGERPI_ETELPI_FUNART' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_EMGERPI_ETELPI_FUNART.FOLHA FO 
    JOIN SW_EMGERPI_ETELPI_FUNART.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_EMGERPI_ETELPI_FUNART.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_ETELPI_FUNART.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_EMGERPI_ETELPI_FUNART.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_EMGERPI_ETELPI_FUNART.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_EMGERPI_ETELPI_FUNART.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_EMGERPI_ETELPI_FUNART.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_EMGERPI_ETELPI_FUNART.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_EMGERPI_ETELPI_FUNART.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_EMGERPI_ETELPI_FUNART.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_EMGERPI_ETELPI_FUNART.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_EMGERPI_ETELPI_FUNART.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_EMGERPI_ETELPI_FUNART.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_EMGERPI_ETELPI_FUNART.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_EMGERPI_ETELPI_FUNART.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_EMGERPI_ETELPI_FUNART.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_ETELPI_FUNART.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_EMGERPI_ETELPI_FUNART.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_EMGERPI_ETELPI_FUNART.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_ETELPI_FUNART.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_EMGERPI_ETELPI_FUNART.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_EMGERPI_ETELPI_FUNART.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_EMGERPI_ETELPI_FUNART.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

