    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_FUESPI.FOLHA FO 
    JOIN SW_FUESPI.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_FUESPI.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_FUESPI.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_FUESPI.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_FUESPI.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_FUESPI.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_FUESPI.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_FUESPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_FUESPI.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_FUESPI.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_FUESPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_FUESPI.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_FUESPI.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_FUESPI.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_FUESPI.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_FUESPI.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_FUESPI.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_FUESPI.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_FUESPI.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_FUESPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_FUESPI.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_FUESPI.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_FUESPI.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'FUNPREV' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    PC1.CPF_PESSOA CPF_INSTITUIDOR,
    FF.MATR_SERVIDOR MATRICULA_INSTITUIDOR,
    HN1.NOME NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_FUNPREV.FOLHA FO 
    JOIN SW_FUNPREV.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_FUNPREV.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_FUNPREV.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_FUNPREV.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_FUNPREV.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_FUNPREV.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_FUNPREV.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_FUNPREV.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_FUNPREV.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_FUNPREV.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_FUNPREV.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_FUNPREV.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_FUNPREV.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_FUNPREV.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_FUNPREV.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_FUNPREV.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_FUNPREV.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_FUNPREV.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_FUNPREV.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO)
    LEFT JOIN SW_FUNPREV.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO) 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO)
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO)
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO)
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO)
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_FUNPREV.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_FUNPREV.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_FUNPREV.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO) AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = NVL(FF.ID_PESSOA_DEPENDENTE, FF.ID_PESSOA_FUNCIONARIO) AND PC.DATA_BAIXA IS NULL
    LEFT JOIN SW_FUNPREV.FUNC_PENSAO_CIVIL FPC ON FPC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.PESSOA_DECLARACAO_FAMILIA PDF ON PDF.ID_DECLARACAO_FAMILIA = FPC.ID_DECLARACAO_FAMILIA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN1 ON HN1.ID_PESSOA = PDF.ID_PESSOA_TITULAR AND HN1.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC1 ON PC1.ID_PESSOA = PDF.ID_PESSOA_TITULAR AND PC1.DATA_BAIXA IS NULL   
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'FUPIP' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_FUPIP.FOLHA FO 
    JOIN SW_FUPIP.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_FUPIP.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_FUPIP.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_FUPIP.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_FUPIP.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_FUPIP.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_FUPIP.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_FUPIP.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_FUPIP.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_FUPIP.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_FUPIP.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_FUPIP.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_FUPIP.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_FUPIP.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_FUPIP.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_FUPIP.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_FUPIP.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_FUPIP.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_FUPIP.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_FUPIP.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_FUPIP.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_FUPIP.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_FUPIP.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'GMG' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_GMG.FOLHA FO 
    JOIN SW_GMG.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_GMG.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_GMG.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_GMG.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_GMG.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_GMG.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_GMG.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_GMG.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_GMG.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_GMG.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_GMG.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_GMG.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_GMG.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_GMG.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_GMG.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_GMG.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_GMG.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_GMG.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_GMG.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_GMG.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_GMG.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_GMG.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_GMG.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'IASPI' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_IASPI.FOLHA FO 
    JOIN SW_IASPI.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_IASPI.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_IASPI.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_IASPI.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_IASPI.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_IASPI.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_IASPI.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_IASPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_IASPI.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_IASPI.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_IASPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_IASPI.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_IASPI.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_IASPI.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_IASPI.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_IASPI.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_IASPI.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_IASPI.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_IASPI.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_IASPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_IASPI.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_IASPI.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_IASPI.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'IDEPI' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_IDEPI.FOLHA FO 
    JOIN SW_IDEPI.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_IDEPI.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_IDEPI.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_IDEPI.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_IDEPI.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_IDEPI.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_IDEPI.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_IDEPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_IDEPI.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_IDEPI.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_IDEPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_IDEPI.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_IDEPI.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_IDEPI.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_IDEPI.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_IDEPI.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_IDEPI.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_IDEPI.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_IDEPI.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_IDEPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_IDEPI.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_IDEPI.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_IDEPI.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'IMEPI' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_IMEPI.FOLHA FO 
    JOIN SW_IMEPI.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_IMEPI.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_IMEPI.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_IMEPI.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_IMEPI.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_IMEPI.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_IMEPI.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_IMEPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_IMEPI.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_IMEPI.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_IMEPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_IMEPI.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_IMEPI.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_IMEPI.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_IMEPI.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_IMEPI.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_IMEPI.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_IMEPI.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_IMEPI.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_IMEPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_IMEPI.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_IMEPI.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_IMEPI.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'IMEPIPROD' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_IMEPIPROD.FOLHA FO 
    JOIN SW_IMEPIPROD.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_IMEPIPROD.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_IMEPIPROD.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_IMEPIPROD.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_IMEPIPROD.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_IMEPIPROD.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_IMEPIPROD.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_IMEPIPROD.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_IMEPIPROD.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_IMEPIPROD.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_IMEPIPROD.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_IMEPIPROD.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_IMEPIPROD.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_IMEPIPROD.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_IMEPIPROD.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_IMEPIPROD.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_IMEPIPROD.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_IMEPIPROD.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_IMEPIPROD.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_IMEPIPROD.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_IMEPIPROD.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_IMEPIPROD.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_IMEPIPROD.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'INTERPI' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_INTERPI.FOLHA FO 
    JOIN SW_INTERPI.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_INTERPI.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_INTERPI.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_INTERPI.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_INTERPI.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_INTERPI.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_INTERPI.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_INTERPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_INTERPI.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_INTERPI.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_INTERPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_INTERPI.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_INTERPI.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_INTERPI.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_INTERPI.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_INTERPI.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_INTERPI.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_INTERPI.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_INTERPI.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_INTERPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_INTERPI.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_INTERPI.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_INTERPI.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'JUCEPI' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_JUCEPI.FOLHA FO 
    JOIN SW_JUCEPI.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_JUCEPI.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_JUCEPI.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_JUCEPI.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_JUCEPI.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_JUCEPI.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_JUCEPI.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_JUCEPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_JUCEPI.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_JUCEPI.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_JUCEPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_JUCEPI.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_JUCEPI.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_JUCEPI.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_JUCEPI.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_JUCEPI.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_JUCEPI.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_JUCEPI.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_JUCEPI.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_JUCEPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_JUCEPI.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_JUCEPI.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_JUCEPI.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'METRO' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_METRO.FOLHA FO 
    JOIN SW_METRO.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_METRO.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_METRO.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_METRO.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_METRO.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_METRO.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_METRO.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_METRO.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_METRO.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_METRO.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_METRO.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_METRO.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_METRO.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_METRO.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_METRO.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_METRO.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_METRO.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_METRO.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_METRO.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_METRO.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_METRO.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_METRO.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_METRO.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'PGEPI' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_PGEPI.FOLHA FO 
    JOIN SW_PGEPI.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_PGEPI.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_PGEPI.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_PGEPI.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_PGEPI.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_PGEPI.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PGEPI.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_PGEPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_PGEPI.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_PGEPI.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_PGEPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_PGEPI.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_PGEPI.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_PGEPI.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_PGEPI.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_PGEPI.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PGEPI.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_PGEPI.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_PGEPI.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PGEPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_PGEPI.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PGEPI.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_PGEPI.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'PMPI' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_PMPI.FOLHA FO 
    JOIN SW_PMPI.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_PMPI.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_PMPI.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_PMPI.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_PMPI.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_PMPI.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PMPI.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_PMPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_PMPI.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_PMPI.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_PMPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_PMPI.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_PMPI.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_PMPI.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_PMPI.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_PMPI.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PMPI.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_PMPI.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_PMPI.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PMPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_PMPI.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PMPI.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_PMPI.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SADA' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SADA.FOLHA FO 
    JOIN SW_SADA.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SADA.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SADA.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SADA.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SADA.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SADA.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SADA.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SADA.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SADA.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SADA.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SADA.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SADA.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SADA.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SADA.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SADA.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SADA.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SADA.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SADA.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SADA.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SADA.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SADA.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SADA.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SADA.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SAF' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SAF.FOLHA FO 
    JOIN SW_SAF.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SAF.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SAF.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SAF.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SAF.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SAF.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SAF.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SAF.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SAF.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SAF.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SAF.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SAF.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SAF.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SAF.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SAF.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SAF.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SAF.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SAF.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SAF.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SAF.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SAF.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SAF.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SAF.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SASC' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SASC.FOLHA FO 
    JOIN SW_SASC.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SASC.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SASC.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SASC.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SASC.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SASC.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SASC.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SASC.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SASC.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SASC.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SASC.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SASC.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SASC.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SASC.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SASC.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SASC.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SASC.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SASC.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SASC.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SASC.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SASC.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SASC.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SASC.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SEADPREVPI' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SEADPREVPI.FOLHA FO 
    JOIN SW_SEADPREVPI.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SEADPREVPI.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SEADPREVPI.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SEADPREVPI.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SEADPREVPI.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SEADPREVPI.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SEADPREVPI.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SEADPREVPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SEADPREVPI.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SEADPREVPI.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SEADPREVPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SEADPREVPI.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SEADPREVPI.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SEADPREVPI.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SEADPREVPI.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SEADPREVPI.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SEADPREVPI.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SEADPREVPI.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SEADPREVPI.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SEADPREVPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SEADPREVPI.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SEADPREVPI.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SEADPREVPI.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SEAGRO' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SEAGRO.FOLHA FO 
    JOIN SW_SEAGRO.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SEAGRO.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SEAGRO.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SEAGRO.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SEAGRO.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SEAGRO.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SEAGRO.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SEAGRO.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SEAGRO.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SEAGRO.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SEAGRO.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SEAGRO.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SEAGRO.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SEAGRO.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SEAGRO.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SEAGRO.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SEAGRO.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SEAGRO.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SEAGRO.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SEAGRO.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SEAGRO.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SEAGRO.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SEAGRO.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SECESP' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SECESP.FOLHA FO 
    JOIN SW_SECESP.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SECESP.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SECESP.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SECESP.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SECESP.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SECESP.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SECESP.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SECESP.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SECESP.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SECESP.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SECESP.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SECESP.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SECESP.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SECESP.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SECESP.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SECESP.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SECESP.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SECESP.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SECESP.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SECESP.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SECESP.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SECESP.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SECESP.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SECID' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SECID.FOLHA FO 
    JOIN SW_SECID.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SECID.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SECID.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SECID.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SECID.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SECID.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SECID.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SECID.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SECID.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SECID.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SECID.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SECID.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SECID.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SECID.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SECID.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SECID.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SECID.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SECID.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SECID.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SECID.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SECID.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SECID.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SECID.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SECMULHERES' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SECMULHERES.FOLHA FO 
    JOIN SW_SECMULHERES.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SECMULHERES.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SECMULHERES.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SECMULHERES.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SECMULHERES.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SECMULHERES.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SECMULHERES.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SECMULHERES.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SECMULHERES.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SECMULHERES.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SECMULHERES.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SECMULHERES.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SECMULHERES.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SECMULHERES.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SECMULHERES.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SECMULHERES.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SECMULHERES.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SECMULHERES.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SECMULHERES.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SECMULHERES.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SECMULHERES.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SECMULHERES.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SECMULHERES.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SECULT' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SECULT.FOLHA FO 
    JOIN SW_SECULT.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SECULT.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SECULT.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SECULT.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SECULT.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SECULT.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SECULT.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SECULT.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SECULT.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SECULT.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SECULT.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SECULT.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SECULT.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SECULT.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SECULT.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SECULT.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SECULT.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SECULT.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SECULT.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SECULT.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SECULT.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SECULT.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SECULT.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SEDET' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SEDET.FOLHA FO 
    JOIN SW_SEDET.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SEDET.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SEDET.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SEDET.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SEDET.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SEDET.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SEDET.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SEDET.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SEDET.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SEDET.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SEDET.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SEDET.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SEDET.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SEDET.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SEDET.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SEDET.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SEDET.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SEDET.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SEDET.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SEDET.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SEDET.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SEDET.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SEDET.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SEDUC' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SEDUC.FOLHA FO 
    JOIN SW_SEDUC.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SEDUC.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SEDUC.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SEDUC.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SEDUC.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SEDUC.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SEDUC.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SEDUC.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SEDUC.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SEDUC.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SEDUC.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SEDUC.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SEDUC.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SEDUC.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SEDUC.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SEDUC.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SEDUC.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SEDUC.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SEDUC.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SEDUC.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SEDUC.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SEDUC.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SEDUC.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SEFAZPI' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SEFAZPI.FOLHA FO 
    JOIN SW_SEFAZPI.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SEFAZPI.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SEFAZPI.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SEFAZPI.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SEFAZPI.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SEFAZPI.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SEFAZPI.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SEFAZPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SEFAZPI.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SEFAZPI.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SEFAZPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SEFAZPI.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SEFAZPI.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SEFAZPI.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SEFAZPI.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SEFAZPI.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SEFAZPI.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SEFAZPI.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SEFAZPI.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SEFAZPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SEFAZPI.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SEFAZPI.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SEFAZPI.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SEGOV' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SEGOV.FOLHA FO 
    JOIN SW_SEGOV.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SEGOV.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SEGOV.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SEGOV.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SEGOV.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SEGOV.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SEGOV.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SEGOV.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SEGOV.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SEGOV.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SEGOV.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SEGOV.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SEGOV.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SEGOV.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SEGOV.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SEGOV.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SEGOV.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SEGOV.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SEGOV.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SEGOV.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SEGOV.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SEGOV.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SEGOV.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SEID' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SEID.FOLHA FO 
    JOIN SW_SEID.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SEID.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SEID.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SEID.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SEID.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SEID.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SEID.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SEID.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SEID.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SEID.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SEID.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SEID.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SEID.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SEID.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SEID.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SEID.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SEID.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SEID.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SEID.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SEID.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SEID.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SEID.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SEID.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SEINFRA' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SEINFRA.FOLHA FO 
    JOIN SW_SEINFRA.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SEINFRA.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SEINFRA.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SEINFRA.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SEINFRA.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SEINFRA.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SEINFRA.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SEINFRA.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SEINFRA.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SEINFRA.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SEINFRA.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SEINFRA.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SEINFRA.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SEINFRA.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SEINFRA.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SEINFRA.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SEINFRA.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SEINFRA.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SEINFRA.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SEINFRA.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SEINFRA.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SEINFRA.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SEINFRA.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SEJUSPI' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SEJUSPI.FOLHA FO 
    JOIN SW_SEJUSPI.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SEJUSPI.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SEJUSPI.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SEJUSPI.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SEJUSPI.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SEJUSPI.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SEJUSPI.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SEJUSPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SEJUSPI.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SEJUSPI.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SEJUSPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SEJUSPI.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SEJUSPI.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SEJUSPI.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SEJUSPI.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SEJUSPI.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SEJUSPI.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SEJUSPI.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SEJUSPI.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SEJUSPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SEJUSPI.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SEJUSPI.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SEJUSPI.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SEMAR' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SEMAR.FOLHA FO 
    JOIN SW_SEMAR.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SEMAR.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SEMAR.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SEMAR.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SEMAR.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SEMAR.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SEMAR.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SEMAR.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SEMAR.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SEMAR.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SEMAR.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SEMAR.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SEMAR.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SEMAR.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SEMAR.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SEMAR.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SEMAR.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SEMAR.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SEMAR.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SEMAR.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SEMAR.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SEMAR.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SEMAR.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SEMINPER' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SEMINPER.FOLHA FO 
    JOIN SW_SEMINPER.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SEMINPER.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SEMINPER.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SEMINPER.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SEMINPER.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SEMINPER.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SEMINPER.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SEMINPER.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SEMINPER.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SEMINPER.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SEMINPER.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SEMINPER.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SEMINPER.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SEMINPER.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SEMINPER.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SEMINPER.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SEMINPER.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SEMINPER.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SEMINPER.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SEMINPER.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SEMINPER.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SEMINPER.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SEMINPER.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SEPLAN' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SEPLAN.FOLHA FO 
    JOIN SW_SEPLAN.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SEPLAN.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SEPLAN.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SEPLAN.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SEPLAN.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SEPLAN.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SEPLAN.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SEPLAN.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SEPLAN.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SEPLAN.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SEPLAN.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SEPLAN.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SEPLAN.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SEPLAN.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SEPLAN.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SEPLAN.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SEPLAN.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SEPLAN.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SEPLAN.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SEPLAN.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SEPLAN.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SEPLAN.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SEPLAN.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SERES' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SERES.FOLHA FO 
    JOIN SW_SERES.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SERES.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SERES.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SERES.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SERES.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SERES.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SERES.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SERES.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SERES.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SERES.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SERES.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SERES.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SERES.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SERES.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SERES.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SERES.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SERES.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SERES.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SERES.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SERES.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SERES.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SERES.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SERES.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SESAPI' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SESAPI.FOLHA FO 
    JOIN SW_SESAPI.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SESAPI.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SESAPI.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SESAPI.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SESAPI.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SESAPI.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SESAPI.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SESAPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SESAPI.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SESAPI.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SESAPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SESAPI.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SESAPI.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SESAPI.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SESAPI.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SESAPI.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SESAPI.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SESAPI.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SESAPI.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SESAPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SESAPI.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SESAPI.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SESAPI.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SETRANS' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SETRANS.FOLHA FO 
    JOIN SW_SETRANS.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SETRANS.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SETRANS.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SETRANS.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SETRANS.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SETRANS.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SETRANS.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SETRANS.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SETRANS.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SETRANS.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SETRANS.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SETRANS.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SETRANS.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SETRANS.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SETRANS.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SETRANS.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SETRANS.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SETRANS.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SETRANS.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SETRANS.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SETRANS.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SETRANS.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SETRANS.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SETRE' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SETRE.FOLHA FO 
    JOIN SW_SETRE.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SETRE.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SETRE.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SETRE.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SETRE.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SETRE.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SETRE.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SETRE.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SETRE.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SETRE.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SETRE.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SETRE.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SETRE.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SETRE.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SETRE.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SETRE.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SETRE.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SETRE.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SETRE.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SETRE.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SETRE.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SETRE.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SETRE.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SETUR' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SETUR.FOLHA FO 
    JOIN SW_SETUR.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SETUR.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SETUR.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SETUR.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SETUR.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SETUR.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SETUR.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SETUR.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SETUR.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SETUR.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SETUR.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SETUR.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SETUR.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SETUR.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SETUR.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SETUR.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SETUR.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SETUR.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SETUR.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SETUR.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SETUR.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SETUR.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SETUR.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SIA' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SIA.FOLHA FO 
    JOIN SW_SIA.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SIA.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SIA.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SIA.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SIA.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SIA.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SIA.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SIA.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SIA.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SIA.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SIA.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SIA.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SIA.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SIA.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SIA.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SIA.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SIA.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SIA.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SIA.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SIA.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SIA.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SIA.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SIA.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SSPPI' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SSPPI.FOLHA FO 
    JOIN SW_SSPPI.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SSPPI.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SSPPI.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SSPPI.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SSPPI.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SSPPI.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SSPPI.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SSPPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SSPPI.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SSPPI.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SSPPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SSPPI.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SSPPI.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SSPPI.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SSPPI.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SSPPI.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SSPPI.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SSPPI.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SSPPI.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SSPPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SSPPI.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SSPPI.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SSPPI.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'SURPI' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_SURPI.FOLHA FO 
    JOIN SW_SURPI.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_SURPI.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_SURPI.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_SURPI.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_SURPI.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_SURPI.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_SURPI.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_SURPI.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_SURPI.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SURPI.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_SURPI.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_SURPI.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_SURPI.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_SURPI.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_SURPI.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_SURPI.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SURPI.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SURPI.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_SURPI.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_SURPI.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_SURPI.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SURPI.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_SURPI.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'TVANTARES' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_TVANTARES.FOLHA FO 
    JOIN SW_TVANTARES.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_TVANTARES.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_TVANTARES.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_TVANTARES.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_TVANTARES.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_TVANTARES.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_TVANTARES.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_TVANTARES.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_TVANTARES.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_TVANTARES.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_TVANTARES.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_TVANTARES.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_TVANTARES.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_TVANTARES.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_TVANTARES.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_TVANTARES.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_TVANTARES.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_TVANTARES.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_TVANTARES.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_TVANTARES.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_TVANTARES.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_TVANTARES.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_TVANTARES.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026

UNION ALL

SELECT 
    'VICEGOV' ORGAO,
    FO.CHAVE_FOLHA,
    FO.DESCRICAO,
    RCR.NOME_REFERENCIA REFERENCIA,
    HN.NOME,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'I') DEPENDENTE_IR,
    (SELECT COUNT(FIS.ID_FUNC_DEPENDENTE_IR_SF) FROM SW_SEFAZPI.FUNC_DEPENDENTE_IR_SF FIS WHERE FIS.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FIS.IND_BENEFICIO = 'S') DEPENDENTE_SF,
    FF.JOIA_PREVIDENCIA_PRIVADA JOIA_PREVIDENCIA,
    RFG.NOME_GRATIFICACAO GRATIFICACAO,
    CCF.NOME_CATEGORIA_FUNCIONAL CARGO_EFETIVO,
    CCE.NOME_ESPECIALIDADE ESPECIALIDADE,
    RFC.NOME_FUNCAO_COMISSIONADA CARGO_COMISSAO,
    PD.NOME_DIVISAO DIVISAO,
    PS.NOME_SITUACAO SITUACAO,
    PTF.NOME_TIPO_FUNCIONARIO TIPO_SERVIDOR,
    PE.DATA_NASCIMENTO,
    FI.DATA_POSSE DATA_ADMISSAO,
    FI.DATA_POSSE,
    L.NOME_LOTACAO LOTACAO,
    RCC.NOME_CENTRO_CUSTO CENTRO,
    FF.CONTRIBUICAO_PREV_PRIVADA,
    B.BANCO_DESCRICAO NOME_BANCO,
    BA.NOME_AGENCIA,
    LTRIM(PB.CONTA_CORRENTE, '0') CONTA_BANCO, 
    A.DATA_APOSENTADORIA,
    PPA.IND_TIPO_CALCULO CALCULO,
    RA.NOME_APOSENTADORIA,
    AR.NOME_REGRA REGRA,
    '' CPF_INSTITUIDOR,
    '' MATRICULA_INSTITUIDOR,
    '' NOME_INSTITUIDOR,
    PE.DATA_OBITO,
    FS.NOME_SEXO SEXO,
    PEC.NOME_ESTADO_CIVIL ESTADO_CIVIL,
    FRC.NOME_RACA_COR,
    CFFR.NOME_TIPO_SANGUE TIPO_SANGUE,
    PCF.IND_CAPACIDADE_TRABALHO,
    PCF.IND_DEF_AUDITIVA,
    PCF.IND_DEF_FISICA,
    PCF.IND_DEF_INTELECTUAL,
    PCF.IND_DEF_MENTAL,
    PCF.IND_DEF_VISUAL,
    CFD.NOME_DEFICIENCIA,
    PEN.DDD_CELULAR,
    PEN.CELULAR,
    PEN.DDD,
    PEN.TELEFONE_RESIDENCIA TELEFONE,
    PEN.LOGRADOURO,
    PEN.NUMERO_ENDERECO,
    PEN.BAIRRO_ENDERECO BAIRRO,
    PEN.CIDADE_CIDADE CIDADE,
    PEN.CEP,
    PEN.COMPLEMENTO_ENDERECO COMPLEMENTO,
    PEM.EMAIL,
    PE.EMAIL_ALTERNATIVO,
    VCC.DESCRICAO FUNCAO_NOMEACAO,
    RT.NOME_REGIME,
    CCF.COD_CATEGORIA_FUNCIONAL CATEGORIA_SERVIDOR,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA_SERVIDOR,
    IE.NOME_ESCOLARIDADE ESCOLARIDADE,
    IC.NOME_CURSO FORMACAO,
    PP.NOME_PLANO PLANO,
    CC.NOME_CLASSE CLASSE,
    CP.NOME_PADRAO PADRAO,
    L.COD_LOTACAO,
    LE.CIDADE_CIDADE CIDADE_LOTACAO,
    FFR1.VALOR_CALCULADO BRUTO_999997,
    FFR2.VALOR_CALCULADO LIQUIDO_999999,
    R.COD_RUBRICA,
    R.NOME_RUBRICA,
    R.TIPO TIPO_RUBRICA,
    FFR.PRAZO_PARCELA PRAZO_RUBRICA,
    FFR.VALOR_CALCULADO VALOR,
    FFR1.VALOR_CALCULADO TOTAL_RECEBIMENTO,
    FFR2.VALOR_CALCULADO TOTAL_DESCONTO,
    NVL(FFR1.VALOR_CALCULADO, 0) - NVL(FFR2.VALOR_CALCULADO, 0) TOTAL_LIQUIDO 
FROM 
    SW_VICEGOV.FOLHA FO 
    JOIN SW_VICEGOV.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN SW_VICEGOV.FOLHA_FUNC_RUBRICA FFR ON FFR.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO
    LEFT JOIN SW_VICEGOV.FOLHA_FUNC_RUBRICA FFR1 ON FFR1.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR1.ID_RUBRICA = 51027
    LEFT JOIN SW_VICEGOV.FOLHA_FUNC_RUBRICA FFR2 ON FFR2.ID_FOLHA_FUNCIONARIO = FF.ID_FOLHA_FUNCIONARIO AND FFR2.ID_RUBRICA = 51025
    LEFT JOIN SW_PUBLICO.FOLHA_RUBRICA R ON R.ID_RUBRICA = FFR.ID_RUBRICA 
    LEFT JOIN SW_VICEGOV.FUNCIONARIO_FUNCAO FUNC ON FUNC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FUNC.DATA_FIM IS NULL
    LEFT JOIN SW_VICEGOV.RHB_FC_FUNCAO_COMISSIONADA RFC ON RFC.ID_FUNCAO_COMISSIONADA = FUNC.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_VICEGOV.RHB_FC_GRATIFICACAO RFG ON RFG.ID_GRATIFICACAO = RFC.ID_GRATIFICACAO
    LEFT JOIN SW_VICEGOV.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_VICEGOV.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_VICEGOV.RHB_CARREIRA_REFERENCIA RCR ON RCR.ID_REFERENCIA = FR.ID_REFERENCIA 
    LEFT JOIN SW_VICEGOV.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INGRESSO_REGIME_TRABALHO RT ON RT.ID_REGIME = FI.ID_REGIME 
    LEFT JOIN SW_VICEGOV.RHB_CARREIRA_CLASSE CC ON CC.ID_CLASSE = FI.ID_CLASSE_INICIAL
    LEFT JOIN SW_VICEGOV.RHB_CARREIRA_PADRAO CP ON CP.ID_PADRAO = FI.ID_PADRAO_INICIAL
    LEFT JOIN SW_VICEGOV.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLANO PP ON PP.ID_PLANO = CCF.ID_PLANO_PREV_PROP
    LEFT JOIN SW_VICEGOV.RHB_CARREIRA_CATEG_ESPECIALID CCE ON CCE.ID_ESPECIALIDADE = FR.ID_ESPECIALIDADE
    LEFT JOIN SW_VICEGOV.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_VICEGOV.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_VICEGOV.RHB_LOTACAO_ENDERECO LE ON LE.ID_LOTACAO = FL.ID_LOTACAO
    LEFT JOIN SW_VICEGOV.FUNC_APOSENTADORIA A ON A.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA RA ON RA.ID_TIPO_APOSENTADORIA = A.ID_TIPO_APOSENTADORIA
    LEFT JOIN SW_PUBLICO.RHB_APOSENTADORIA_REGRA AR ON AR.ID_REGRA = A.ID_REGRA_TIPO
    LEFT JOIN SW_PUBLICO.PREV_PROP_PLAN_PREV_APOSENT PPA ON PPA.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_VICEGOV.RHB_PERFIL P ON P.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_DIVISAO PD ON PD.ID_DIVISAO = P.ID_DIVISAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = P.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_TIPO_FUNCIONARIO PTF ON PTF.ID_TIPO_FUNCIONARIO = FP.ID_TIPO_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA PE ON PE.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO 
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = PE.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_ESCOLARIDADE PES ON PES.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_CURSO IC ON IC.ID_CURSO = PES.ID_CURSO
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = PE.ID_PESSOA
    LEFT JOIN SW_PUBLICO.PESSOA_BANCO PB ON PB.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_BANCO B ON B.ID_BANCO = PB.ID_PESSOA_BANCO
    LEFT JOIN SW_PUBLICO.RHB_BANCO_AGENCIA BA ON BA.ID_AGENCIA = PB.ID_AGENCIA
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = PE.ID_SEXO
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL EC ON EC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL PEC ON PEC.ID_ESTADO_CIVIL = EC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA PCF ON PCF.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_RACA_COR FRC ON FRC.ID_RACA_COR = PCF.ID_RACA_COR
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_FATOR_RH CFFR ON CFFR.ID_TIPO_SANGUE = PCF.ID_TIPO_SANGUE
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_DEFICIENCIA CFD ON CFD.ID_DEFICIENCIA = PCF.ID_DEFICIENCIA
    LEFT JOIN SW_VICEGOV.FUNC_CENTRO_CUSTO FCC ON FCC.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_VICEGOV.RHB_CENTRO_CUSTO RCC ON RCC.ID_CENTRO_CUSTO = FCC.ID_CENTRO_CUSTO
    LEFT JOIN SW_VICEGOV.FUNCIONARIO_FUNCAO_NOMEACAO FFN ON FFN.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.NM_VAGA_CARGO_COMISSIONADO VCC ON VCC.ID_NM_VAGA_CARGO_COMISSIONADO = FFN.ID_FUNCAO_COMISSIONADA
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
WHERE 
    FO.MES = 8
    AND FO.ANO = 2026